const verificationSource=`// Replay recorded actual history only; no search or move recommendations.
module.exports=function(log,inspect){
 const cols="ABCDEFGHJ", board={}, captures={X:0,O:0}, states=new Map(); let ko=null, checks=[];
 for(const c of cols)for(let r=1;r<=9;r++)board[c+r]=".";
 const ns=p=>{let i=cols.indexOf(p[0]),r=+p[1];return [[i-1,r],[i+1,r],[i,r-1],[i,r+1]].filter(([j,y])=>j>=0&&j<9&&y>=1&&y<=9).map(([j,y])=>cols[j]+y)};
 const group=p=>{let color=board[p],stones=[],libs=new Set(),seen=new Set([p]),todo=[p];while(todo.length){let q=todo.pop();stones.push(q);for(const n of ns(q)){if(board[n]===".")libs.add(n);else if(board[n]===color&&!seen.has(n)){seen.add(n);todo.push(n)}}}return {stones,libs:[...libs]}};
 for(const m of log.moves){const col=m.color==="B"?"X":"O",enemy=col==="X"?"O":"X";if(m.move==="pass")ko=null;else{if(board[m.move]!=="."||m.move===ko)throw Error("illegal occupied/ko "+m.n);board[m.move]=col;let removed=[];for(const n of ns(m.move))if(board[n]===enemy){const g=group(n);if(g.libs.length===0){for(const p of g.stones)board[p]=".";removed.push(...g.stones)}}const own=group(m.move);if(!own.libs.length)throw Error("suicide "+m.n);captures[col]+=removed.length;ko=removed.length===1&&own.stones.length===1&&own.libs.length===1?removed[0]:null}states.set(m.n,{board:{...board},captures:{...captures},ko});}
 for(const raw of log.raw){const s=raw.response.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n"),next=+s.match(/Move number: (\\d+)/)[1],actual=next-1,want=states.get(actual),got=inspect(raw.response);for(const p of Object.keys(board))if(want.board[p]!==got.board[p])throw Error("board mismatch "+actual+" "+p);const cap=s.match(/Captured by Black: (\\d+); by White: (\\d+)/),marker=s.match(/Ko point: ([^.]+)\\./)[1];if(+cap[1]!==want.captures.X||+cap[2]!==want.captures.O||marker!==(want.ko||"none"))throw Error("state mismatch "+actual);checks.push({actual,board:true,captures:true,ko:true,moveNumber:true});}
 return {legalActualMoves:log.moves.length,matchingRawSnapshots:checks.length,checks,finalCaptures:captures};
};`;
store("verificationSource",verificationSource);
const inspect=new Function(load("inspectSrc").replace("module.exports = inspect;","return inspect;"))(); const verify=new Function(verificationSource.replace("module.exports=function","return function"))();
const log={moves:load("moves86"),raw:load("raw86")};const v=verify(log,inspect);store("verification86",v);text(v);
const dead=["A2","A3","B3","C1","C2","C3","F2","G2","H2","J2"];const b={...load("inspect65").board};dead.forEach(p=>b[p]=".");const raw={content:[{type:"text",text:[9,8,7,6,5,4,3,2,1].map(r=>r+" "+[..."ABCDEFGHJ"].map(c=>b[c+r]).join(" ")+" "+r).join("\n")}]};const cleaned=inspect(raw);store("cleaned86",cleaned);store("dead86",dead);text({cleanedArea:cleaned.area,regions:cleaned.regions});

